def momento(x, L, carichi):
    x = np.asarray(x, dtype=float)
    RA, _ = reazioni(L, carichi)
    M = RA * x
    for c in carichi:
        if c[0] == "F":
            _, F, a = c
            M -= F * np.maximum(x - a, 0)
        else:
            _, q, a, b = c
            s = np.clip(x - a, 0, b - a)
            M -= q * s * (x - a - s / 2)
    return M
